  --color-pure-black: #000000;
  --color-canvas-mist: #f2f7fd;
  --color-paper-white: #ffffff;
  --color-steel-border: #d6dee6;
  --color-slate-caption: #666e7e;
  --color-shadow-gray: #b3b3b3;
